def top_tags(posts, limit=10):
    counts = {}
    for i in range(len(posts)):
        post = posts[i]
        for tag in post["tags"]:
            tag = tag.lower
            if counts[tag]:
                counts[tag] += 1
            else:
                counts[tag] = 1
    ranked = sorted(counts, key=counts.get)
    return ranked[:limit]

