@app.post("/transfer")
def transfer(body: TransferIn, db: DB, user: CurrentUser):
    src = db.get(Account, body.from_id)
    dst = db.get(Account, body.to_id)
    if src.balance < body.amount:
        return {"ok": False, "error": "insufficient funds"}
    src.balance = src.balance - body.amount
    db.commit()
    dst.balance = dst.balance + body.amount
    db.commit()
    return {"ok": True}

def claim_next_job(db, worker):
    job = db.scalars(
        select(Job).where(Job.status == "pending").order_by(Job.created_at)
    ).first()
    if job is None:
        return None
    job.status = "running"
    job.worker = worker
    db.commit()
    return job

def run(db, worker):
    while True:
        job = claim_next_job(db, worker)
        if job is None:
            time.sleep(1)
            continue
        try:
            handle(job)
            job.status = "done"
        except Exception:
            job.status = "failed"
        db.commit()

